package uz.plugin.audio_player

/**
 * The API Dart calls through JNI (bindings in `lib/src/bindings/audio_player_api.g.dart`, generated by
 * `dart run tool/jnigen.dart` from the compiled classes). It takes only `String`s and callback interfaces, and
 * forwards every call to the engine's [AudioPlayerHost].
 *
 * Requests and replies are the JSON form of the platform interface messages, with the same method names and fields
 * the former method channel used. Results come back through [ResultCallback], playback events through
 * [PlaybackListener]. A call made while no engine is attached fails with the code `detached`.
 */
object AudioPlayerApi {

    /** Answers one call: [onResult] with the JSON reply, or [onError]. */
    interface ResultCallback {
        fun onResult(json: String?)

        fun onError(code: String?, message: String?, details: String?)
    }

    /** Events of every player; `playerId` says which one. */
    interface PlaybackListener {
        /** A playback event (JSON of `PlaybackEventMessage`). */
        fun onPlaybackEvent(playerId: String?, json: String?)

        /** A data update (JSON of `PlayerDataMessage`). */
        fun onPlayerData(playerId: String?, json: String?)

        /** An error reported on the playback event stream; the next playback event carries it as well. */
        fun onPlaybackError(playerId: String?, code: String?, message: String?, details: String?)
    }

    /** Replaces the listener of the current engine; a hot restart registers a new one. */
    @JvmStatic
    fun setPlaybackListener(listener: PlaybackListener?) {
        AudioPlayerHost.current?.setListener(listener)
    }

    /** Calls a plugin-level method: `init`, `disposePlayer` or `disposeAllPlayers`. */
    @JvmStatic
    fun call(method: String, request: String?, callback: ResultCallback) {
        val host = AudioPlayerHost.current
        if (host == null) detached(callback) else host.call(method, request, callback)
    }

    /** Calls a method of the player [playerId]. */
    @JvmStatic
    fun callPlayer(playerId: String, method: String, request: String?, callback: ResultCallback) {
        val host = AudioPlayerHost.current
        if (host == null) detached(callback) else host.callPlayer(playerId, method, request, callback)
    }

    private fun detached(callback: ResultCallback) {
        callback.onError("detached", "No Flutter engine is attached", null)
    }
}
